// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    Receiver bankHolder;

    function setUp() public {
        bankHolder = new Receiver();
        // deploy from a payable-receiving contract so bank transfers of FEE succeed
        vm.prank(address(bankHolder));
        c = new EtherLotto();
    }

    function testFuzz_property(address player, uint256 seed) public {
        vm.assume(player != address(0));
        vm.assume(player != address(c));
        vm.assume(player.code.length == 0); // EOA player: payout transfer to it always succeeds

        vm.warp(seed);
        vm.roll(seed);

        vm.deal(player, 1 ether);
        vm.prank(player);
        bool ok;
        try c.play{value: 10, gas: 200000}() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a properly-priced play never reverts (wins pay out cleanly,
        // losses just accumulate). The mutant reverts on every winning draw.
        assertTrue(ok, "play with exact ticket amount must not revert");
    }
}

contract Receiver {
    receive() external payable {}
}
